import React, { useState, useEffect, useRef } from 'react';
import { 
  Menu, X, Globe, Moon, Sun, ArrowRight, ArrowUpRight,
  ShieldCheck, Package, Truck, Activity, Zap, User, Check, Leaf, Sprout
} from 'lucide-react';
import { TRANSLATIONS, PRODUCTS, LANG_CONFIG } from './constants';
import { Language, Theme } from './types';
import SpecsChart from './components/SpecsChart';
import AboutPage from './components/AboutPage';
import WhyUsPage from './components/WhyUsPage';
import CookieConsent from './components/CookieConsent';

type ViewState = 'home' | 'about' | 'why-us';

function App() {
  const [lang, setLang] = useState<Language>(() => (localStorage.getItem('agrovibe_lang') as Language) || 'EN');
  const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('agrovibe_theme') as Theme) || 'light');
  const [cookieConsent, setCookieConsent] = useState<'accepted' | 'declined' | null>(() => localStorage.getItem('agrovibe_cookie_consent') as 'accepted' | 'declined' | null);
  const [isNavOpen, setIsNavOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);
  const [activeProductIndex, setActiveProductIndex] = useState(0);
  const [scrolled, setScrolled] = useState(false);
  const [view, setView] = useState<ViewState>('home');
  const [worldTimes, setWorldTimes] = useState({ kendari: '', london: '', china: '' });
  const langMenuRef = useRef<HTMLDivElement>(null);

  const t = TRANSLATIONS[lang];
  const products = PRODUCTS[lang];
  const activeProduct = products[activeProductIndex];

  useEffect(() => {
    if (cookieConsent === 'accepted') {
      localStorage.setItem('agrovibe_lang', lang);
      localStorage.setItem('agrovibe_theme', theme);
    }
    document.documentElement.classList.toggle('dark', theme === 'dark');
    document.documentElement.dir = lang === 'AE' ? 'rtl' : 'ltr';
  }, [lang, theme, cookieConsent]);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    const updateTime = () => {
      const getCityTime = (zone: string) => new Date().toLocaleTimeString('en-US', { timeZone: zone, hour: '2-digit', minute: '2-digit', hour12: false });
      setWorldTimes({ kendari: getCityTime('Asia/Makassar'), london: getCityTime('Europe/London'), china: getCityTime('Asia/Shanghai') });
    };
    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, []);

  const handleScrollTo = (e: React.MouseEvent<HTMLElement>, id: string) => {
    e.preventDefault();
    setView('home');
    setIsNavOpen(false);
    setTimeout(() => {
      const element = document.getElementById(id);
      element?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const isDark = theme === 'dark';

  return (
    <div className={`min-h-screen transition-colors duration-700 font-sans selection:bg-brand-500 selection:text-white ${isDark ? 'bg-zinc-950 text-zinc-100' : 'bg-[#f8f8f7] text-zinc-900'} overflow-x-hidden`}>
      <div className="fixed inset-0 pointer-events-none z-0 bg-noise opacity-40 mix-blend-overlay"></div>

      {/* REFINED HEADER: Smaller padding, better containment */}
      <nav className={`fixed top-0 left-0 w-full z-40 transition-all duration-500 ${scrolled ? 'py-2 md:py-3' : 'py-4 md:py-6'}`}>
        <div className="w-[95%] md:max-w-[96%] mx-auto bg-white/80 dark:bg-black/50 backdrop-blur-md border border-white/20 dark:border-white/10 rounded-full px-4 md:px-6 py-2.5 md:py-3 flex justify-between items-center shadow-sm">
          <button onClick={() => setView('home')} className="flex items-center gap-3 group">
             <div className="w-8 h-8 md:w-10 md:h-10 bg-brand-500 rounded-full flex items-center justify-center text-white group-hover:rotate-12 transition-transform shrink-0">
                <Leaf size={16} fill="currentColor" className="md:w-[18px] md:h-[18px]" />
             </div>
             <span className="font-bold text-lg md:text-xl tracking-tighter">AgroVibe<span className="text-brand-500">.</span></span>
          </button>

          <div className="hidden md:flex items-center gap-6 lg:gap-8 text-[11px] lg:text-xs font-bold uppercase tracking-widest">
             <button onClick={() => setView('home')} className={`opacity-60 hover:opacity-100 transition-all ${view === 'home' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.home}</button>
             <button onClick={() => setView('about')} className={`opacity-60 hover:opacity-100 transition-all ${view === 'about' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.about}</button>
             <button onClick={() => setView('why-us')} className={`opacity-60 hover:opacity-100 transition-all ${view === 'why-us' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.whyChooseUs}</button>
             <a href="#products" onClick={(e) => handleScrollTo(e, 'products')} className="opacity-60 hover:opacity-100">{t.nav.products}</a>
          </div>

          <div className="hidden md:flex items-center gap-3">
             <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')} className="w-9 h-9 md:w-10 md:h-10 rounded-full border border-zinc-200 dark:border-zinc-800 flex items-center justify-center hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors">
                {isDark ? <Sun size={16} /> : <Moon size={16} />}
             </button>
             <div className="relative" ref={langMenuRef}>
               <button onClick={() => setIsLangMenuOpen(!isLangMenuOpen)} className="w-9 h-9 md:w-10 md:h-10 rounded-full border border-zinc-200 dark:border-zinc-800 flex items-center justify-center hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors">
                  <Globe size={16} />
               </button>
               {isLangMenuOpen && (
                 <div className="absolute top-full right-0 mt-3 w-44 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-2xl shadow-xl overflow-hidden animate-fade-up z-50 p-1.5 flex flex-col gap-0.5">
                   {(Object.keys(LANG_CONFIG) as Language[]).map((langKey) => (
                     <button key={langKey} onClick={() => { setLang(langKey); setIsLangMenuOpen(false); }} className={`flex items-center justify-between px-3 py-2 text-xs font-bold uppercase tracking-wider rounded-xl transition-colors ${lang === langKey ? 'bg-zinc-100 dark:bg-zinc-800' : 'hover:bg-zinc-50'}`}>
                       <span className="flex items-center gap-3"><span>{LANG_CONFIG[langKey].flag}</span><span>{LANG_CONFIG[langKey].label}</span></span>
                       {lang === langKey && <Check size={14} className="text-brand-500" />}
                     </button>
                   ))}
                 </div>
               )}
             </div>
             <button onClick={() => setIsClientModalOpen(true)} className="px-5 md:px-6 py-2 md:py-2.5 bg-brand-500 text-white rounded-full text-[10px] md:text-xs font-bold uppercase tracking-widest hover:bg-brand-600 transition-all shadow-lg shadow-brand-500/20">{t.nav.client}</button>
          </div>

           <div className="md:hidden flex items-center gap-2">
             <button onClick={() => setIsLangMenuOpen(!isLangMenuOpen)} className="p-2 rounded-full border border-zinc-200 dark:border-zinc-800"><Globe size={18} /></button>
             <button onClick={() => setIsNavOpen(!isNavOpen)} className="p-2 rounded-full bg-zinc-900 dark:bg-white text-white dark:text-zinc-900">{isNavOpen ? <X size={18} /> : <Menu size={18} />}</button>
           </div>
        </div>
      </nav>

      {isNavOpen && (
        <div className="fixed inset-0 z-30 bg-white/95 dark:bg-zinc-950/95 backdrop-blur-xl pt-28 px-6 flex flex-col gap-6 animate-fade-up">
          <div className="flex flex-col gap-3 text-3xl font-black uppercase tracking-tighter italic">
             <button onClick={() => { setView('home'); setIsNavOpen(false); }} className={`text-left ${view === 'home' ? 'text-brand-500' : ''}`}>{t.nav.home}</button>
             <button onClick={() => { setView('about'); setIsNavOpen(false); }} className={`text-left ${view === 'about' ? 'text-brand-500' : ''}`}>{t.nav.about}</button>
             <button onClick={() => { setView('why-us'); setIsNavOpen(false); }} className={`text-left ${view === 'why-us' ? 'text-brand-500' : ''}`}>{t.nav.whyChooseUs}</button>
             <a href="#products" onClick={(e) => handleScrollTo(e, 'products')} className="text-left">{t.nav.products}</a>
          </div>
          <button onClick={() => { setIsNavOpen(false); setIsClientModalOpen(true); }} className="w-full py-4 bg-brand-500 text-white rounded-xl text-lg font-bold uppercase italic tracking-tighter">{t.nav.client}</button>
        </div>
      )}

      {view === 'about' ? <AboutPage t={t} isDark={isDark} /> : view === 'why-us' ? <WhyUsPage t={t} isDark={isDark} /> : (
        <>
          {/* REFINED HERO: Reduced top padding, optimized font sizing */}
          <header className="relative pt-32 md:pt-44 pb-16 md:pb-24 px-4 md:px-12 overflow-hidden">
             <div className="max-w-[95rem] mx-auto grid grid-cols-1 lg:grid-cols-12 gap-10 lg:gap-12 items-end">
                <div className="lg:col-span-8 z-10">
                   <div className="inline-flex items-center gap-3 mb-6 md:mb-8 border border-zinc-200 dark:border-zinc-800 px-3 md:px-4 py-1.5 md:py-2 rounded-full text-[9px] md:text-[10px] uppercase tracking-[0.3em] font-bold animate-fade-up italic bg-white/50 dark:bg-black/50 backdrop-blur-sm"><span className="w-1.5 h-1.5 rounded-full bg-brand-500 animate-pulse"></span>{t.hero.badge}</div>

                   {/* Typography optimized for different breakpoints */}
                   <h1 className="text-[11vw] sm:text-[9vw] md:text-[6rem] lg:text-[7.5rem] xl:text-[8.5rem] font-bold leading-[0.9] md:leading-[0.85] tracking-tighter mb-8 md:mb-10 text-balance animate-fade-up uppercase italic">
                      {t.hero.titleLine1} <br/>
                      <span className="text-brand-500 not-italic">{t.hero.titleLine2}</span>
                   </h1>

                   <p className="text-base md:text-xl opacity-60 max-w-xl leading-relaxed mb-8 md:mb-10 animate-fade-up font-light">{t.hero.subtitle}</p>

                   <div className="flex flex-col sm:flex-row gap-4 md:gap-6 animate-fade-up">
                      <a href="#products" onClick={(e) => handleScrollTo(e, 'products')} className="group px-8 py-4 md:px-10 md:py-5 bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 rounded-full text-[10px] md:text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-4 transition-all hover:bg-brand-500 dark:hover:bg-brand-500 dark:hover:text-white shadow-xl">
                         {t.hero.ctaPrimary} <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                      </a>
                      <button onClick={() => setIsClientModalOpen(true)} className="px-8 py-4 md:px-10 md:py-5 border border-zinc-300 dark:border-zinc-700 rounded-full text-[10px] md:text-xs font-bold uppercase tracking-widest hover:bg-zinc-100 dark:hover:bg-zinc-900 transition-colors">{t.hero.ctaSecondary}</button>
                   </div>
                </div>

                {/* Image sizing optimized */}
                <div className="lg:col-span-4 relative h-[350px] md:h-[500px] lg:h-[550px] w-full animate-reveal overflow-hidden rounded-[2.5rem] md:rounded-[4rem] shadow-2xl border-4 border-white/10 mt-8 lg:mt-0">
                   <img src="https://images.unsplash.com/photo-1599940824399-b87987ce179a?q=80&w=2624&auto=format&fit=crop" className="w-full h-full object-cover scale-110 hover:scale-100 transition-transform duration-[3s]" alt="Spices" />
                   <div className="absolute bottom-6 left-6 right-6 p-5 bg-black/30 backdrop-blur-xl rounded-[1.5rem] border border-white/20">
                      <div className="flex justify-between items-center text-white mb-3"><span className="text-[10px] font-mono uppercase tracking-widest opacity-70">{t.hero.currentVol}</span><span className="font-bold font-mono">350 MT</span></div>
                      <div className="w-full bg-white/20 h-1 rounded-full overflow-hidden"><div className="bg-brand-500 h-full w-[85%] transition-all duration-[2s]"></div></div>
                   </div>
                </div>
             </div>
          </header>

          <div className="w-full bg-brand-500 text-brand-950 py-4 md:py-5 overflow-hidden border-y-2 border-brand-600">
             <div className="flex gap-16 animate-marquee whitespace-nowrap font-fun text-lg md:text-2xl font-black uppercase tracking-tighter items-center italic">
                {Array(10).fill(t.marquee).map((text, i) => <span key={i}>{text}</span>)}
             </div>
          </div>

          {/* PRODUCTS SECTION: Tighter vertical spacing, normalized card height */}
          <section id="products" className="py-20 md:py-32 px-4 md:px-12 bg-white dark:bg-zinc-900">
             <div className="max-w-[95rem] mx-auto">
                <div className="flex flex-col md:flex-row justify-between items-end mb-16 md:mb-20 gap-8 md:gap-12">
                   <div>
                      <h2 className="text-5xl md:text-[6vw] font-bold tracking-tighter leading-none mb-6 uppercase italic">{t.products.title}</h2>
                      <p className="opacity-60 max-w-lg text-lg md:text-xl font-light leading-snug">{t.products.subtitle}</p>
                   </div>
                   <button className="hidden md:flex items-center gap-4 text-[10px] md:text-xs font-black uppercase tracking-[0.4em] hover:text-brand-500 transition-colors border-b-2 border-zinc-900 dark:border-white pb-2">
                      {t.products.viewCatalog} <ArrowRight size={16} />
                   </button>
                </div>

                {/* Grid gap adjusted, Height reduced from 600px to 500px max */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5 md:gap-6">
                   {products.map((product, idx) => (
                      <div key={product.id} onClick={() => setActiveProductIndex(idx)} className={`group relative h-[400px] md:h-[450px] lg:h-[500px] rounded-[2.5rem] overflow-hidden cursor-pointer transition-all duration-700 ${activeProductIndex === idx ? 'ring-2 ring-brand-500 ring-offset-4 dark:ring-offset-zinc-950 scale-[1.02]' : 'hover:scale-[1.01]'}`}>
                         <img src={product.image} className="absolute inset-0 w-full h-full object-cover transition-transform duration-[1.5s] group-hover:scale-110" alt={product.title} />
                         <div className="absolute inset-0 bg-gradient-to-t from-black/95 via-black/30 to-transparent transition-opacity duration-700 opacity-80 group-hover:opacity-100" />
                         <div className="absolute top-6 right-6 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full px-3 py-1.5 text-white text-[9px] font-black uppercase tracking-widest">{product.tags[0]}</div>
                         <div className="absolute bottom-0 left-0 w-full p-6 md:p-8 transform translate-y-6 group-hover:translate-y-0 transition-transform duration-700">
                            <h3 className="text-xl md:text-2xl text-white font-black leading-none mb-3 italic uppercase tracking-tighter">{product.title}</h3>
                            <p className="text-sm text-white/60 font-light line-clamp-3 mb-5 opacity-0 group-hover:opacity-100 transition-opacity duration-700 delay-100 leading-relaxed">{product.description}</p>
                            <div className="w-12 h-12 bg-brand-500 rounded-full flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-all duration-500 hover:rotate-12 hover:scale-110 shadow-2xl"><ArrowUpRight size={24} /></div>
                         </div>
                      </div>
                   ))}
                </div>
             </div>
          </section>

          {/* SPECS SECTION: Reduced vertical padding */}
          <section id="specs" className="py-20 md:py-36 px-4 md:px-12 bg-zinc-50 dark:bg-black relative overflow-hidden">
             <div className="max-w-[95rem] mx-auto relative z-10">
                <div className="flex flex-col lg:flex-row gap-12 lg:gap-32">
                   <div className="lg:w-[40%] lg:sticky lg:top-32 h-fit">
                      <span className="text-brand-500 font-mono text-[10px] md:text-xs uppercase tracking-[0.5em] mb-6 block italic">/// {t.specs.liveDataLabel}</span>
                      <h2 className="text-5xl md:text-7xl lg:text-8xl font-black uppercase tracking-tighter leading-[0.85] mb-8 italic">{t.specs.title}</h2>
                      <p className="text-lg md:text-2xl font-light opacity-70 leading-snug mb-10 md:mb-12">{t.specs.subtitle}</p>
                      <div className="space-y-8">
                         <div className="flex items-center gap-6 group">
                            <div className="w-16 h-16 bg-brand-500/10 text-brand-500 rounded-[1.5rem] flex items-center justify-center shrink-0 border border-brand-500/20 group-hover:rotate-12 transition-transform duration-500"><Activity size={28} /></div>
                            <div><div className="text-xl font-bold mb-1">{t.specs.realTimeTitle}</div><div className="text-[10px] opacity-50 uppercase tracking-widest font-mono">{t.specs.realTimeDesc}</div></div>
                         </div>
                         <div className="flex items-center gap-6 group">
                            <div className="w-16 h-16 bg-brand-500/10 text-brand-500 rounded-[1.5rem] flex items-center justify-center shrink-0 border border-brand-500/20 group-hover:-rotate-12 transition-transform duration-500"><ShieldCheck size={28} /></div>
                            <div><div className="text-xl font-bold mb-1">{t.specs.certTitle}</div><div className="text-[10px] opacity-50 uppercase tracking-widest font-mono">{t.specs.certDesc}</div></div>
                         </div>
                      </div>
                   </div>
                   <div className="lg:w-[60%] space-y-8 md:space-y-10">
                      <div className="bg-white dark:bg-zinc-900 rounded-[3rem] p-8 md:p-16 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.2)] border border-zinc-100 dark:border-zinc-800">
                         <div className="flex justify-between items-start mb-12 md:mb-16">
                            <div><div className="text-5xl md:text-7xl font-black italic tracking-tighter mb-2 tabular-nums">{activeProduct.specs[0].value}<span className="text-brand-500 text-3xl md:text-4xl">{activeProduct.specs[0].unit}</span></div><div className="text-[10px] font-black uppercase tracking-[0.4em] opacity-40 italic">{activeProduct.specs[0].name}</div></div>
                            <div className="bg-brand-500 text-white px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest italic">{t.specs.grade}</div>
                         </div>
                         <SpecsChart data={activeProduct.specs} isDark={isDark} />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-10">
                         <div className="bg-zinc-950 text-white p-10 md:p-12 rounded-[3rem] border border-white/5 hover:border-brand-500/30 transition-all duration-700">
                            <Zap className="mb-8 text-brand-500 group-hover:scale-125 transition-transform" size={40} />
                            <h4 className="text-3xl font-black uppercase mb-4 italic tracking-tighter">{t.specs.efficiencyTitle}</h4>
                            <p className="text-lg opacity-60 font-light leading-relaxed">{t.specs.efficiencyDesc}</p>
                         </div>
                         <div className="bg-white dark:bg-zinc-900 p-10 md:p-12 rounded-[3rem] border border-zinc-100 dark:border-zinc-800 hover:border-brand-500/30 transition-all duration-700">
                            <Sprout className="mb-8 text-brand-500" size={40} />
                            <h4 className="text-3xl font-black uppercase mb-4 italic tracking-tighter">{t.specs.sustainableTitle}</h4>
                            <p className="text-lg opacity-60 font-light leading-relaxed">{t.specs.sustainableDesc}</p>
                         </div>
                      </div>
                   </div>
                </div>
             </div>
          </section>
        </>
      )}

      {/* FOOTER: Reduced Top Padding, Typography Scaling */}
      <footer id="contact" className="bg-zinc-950 text-white relative pt-24 pb-12 px-6 md:px-12 mt-20 rounded-t-[3rem] md:rounded-t-[5rem] overflow-hidden group">
         <div className="max-w-[95rem] mx-auto mb-20 md:mb-24 border-b border-zinc-800 pb-16 flex flex-col lg:flex-row justify-between items-start lg:items-end gap-12 lg:gap-20">
            <div>
               <h2 className="text-[14vw] md:text-[8vw] font-black leading-[0.85] tracking-tighter text-white uppercase italic">
                  {t.footer.ctaPrefix} <br/><span className="text-zinc-700 not-italic">{t.footer.ctaHighlight}</span>
               </h2>
            </div>
            <div className="flex flex-col items-start lg:items-end gap-8 md:gap-10 w-full lg:w-auto">
                <div className="flex flex-wrap gap-4 md:gap-6">
                   {[{ city: 'Kendari', time: worldTimes.kendari, code: 'ID' }, { city: 'London', time: worldTimes.london, code: 'GB' }, { city: 'Shanghai', time: worldTimes.china, code: 'CN' }].map((clock, idx) => (
                     <div key={idx} className="flex items-center gap-4 px-6 py-4 rounded-[1.5rem] border border-white/10 bg-white/5 backdrop-blur-xl">
                        <div className="flex flex-col"><span className="text-[9px] font-mono text-zinc-500 uppercase tracking-widest mb-1">{clock.city}</span><span className="font-fun text-2xl font-black text-brand-500 tabular-nums leading-none tracking-tighter italic">{clock.time}</span></div>
                        <div className="text-xl opacity-40 grayscale">{clock.code === 'ID' ? '🇮🇩' : clock.code === 'GB' ? '🇬🇧' : '🇨🇳'}</div>
                     </div>
                   ))}
                </div>
                <button onClick={() => setIsClientModalOpen(true)} className="w-full md:w-auto px-12 py-6 bg-brand-500 hover:bg-brand-400 text-zinc-950 rounded-full text-xl font-black uppercase italic tracking-tighter transition-all transform hover:scale-105 flex items-center justify-center gap-4 shadow-[0_0_60px_-10px_rgba(16,185,129,0.4)]">
                   {t.footer.startSourcing} <ArrowUpRight size={28} />
                </button>
            </div>
         </div>

         <div className="max-w-[95rem] mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12 md:gap-16 mb-24 md:mb-32">
             <div><span className="block text-[10px] font-mono text-zinc-600 mb-8 uppercase tracking-[0.5em]">/// {t.footer.exploreLabel}</span><ul className="space-y-4 text-xl md:text-2xl font-black uppercase italic tracking-tighter">
                <li><button onClick={() => setView('home')} className="hover:text-brand-500 transition-all duration-500 hover:pl-2">{t.nav.home}</button></li>
                <li><button onClick={() => setView('about')} className="hover:text-brand-500 transition-all duration-500 hover:pl-2">{t.nav.about}</button></li>
                <li><button onClick={() => setView('why-us')} className="hover:text-brand-500 transition-all duration-500 hover:pl-2">{t.nav.whyChooseUs}</button></li>
             </ul></div>
             <div><span className="block text-[10px] font-mono text-zinc-600 mb-8 uppercase tracking-[0.5em]">/// {t.footer.connectLabel}</span><ul className="space-y-4 text-xl md:text-2xl font-black uppercase italic tracking-tighter">
                <li><a href="mailto:hello@agrovibe.tech" className="hover:text-brand-500 transition-all duration-500 hover:pl-2">Email</a></li>
                <li><a href="#" className="hover:text-brand-500 transition-all duration-500 hover:pl-2">LinkedIn</a></li>
                <li><a href="#" className="hover:text-brand-500 transition-all duration-500 hover:pl-2">Instagram</a></li>
             </ul></div>
             <div className="sm:col-span-2"><span className="block text-[10px] font-mono text-zinc-600 mb-8 uppercase tracking-[0.5em]">/// {t.footer.officeLabel}</span><address className="not-italic text-xl md:text-2xl text-zinc-400 font-light leading-snug mb-8 whitespace-pre-line tracking-tight">{t.footer.address}</address><a href="mailto:hello@agrovibe.tech" className="text-2xl md:text-4xl font-black hover:text-brand-500 transition-colors border-b-4 border-zinc-800 hover:border-brand-500 pb-2 inline-block italic tracking-tighter uppercase">hello@agrovibe.tech</a></div>
