               <button type="submit" className="w-full bg-brand-500 hover:bg-brand-600 text-white font-black uppercase italic tracking-tighter text-xl py-5 rounded-xl transition-all shadow-xl hover:shadow-brand-500/30 transform hover:scale-[1.02] active:scale-95">{t.clientForm.submit}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
