             <div className="sm:col-span-2"><span className="block text-[10px] font-mono text-zinc-600 mb-8 uppercase tracking-[0.5em]">/// {t.footer.officeLabel}</span><address className="not-italic text-lg md:text-xl text-zinc-400 font-light leading-snug mb-8 whitespace-pre-line tracking-tight">{t.footer.address}</address><a href="mailto:hello@agrovibe.tech" className="text-xl md:text-3xl font-black hover:text-brand-500 transition-colors border-b-4 border-zinc-800 hover:border-brand-500 pb-2 inline-block italic tracking-tighter uppercase">hello@agrovibe.tech</a></div>
         </div>

         <div className="max-w-[95rem] mx-auto border-t border-zinc-800 pt-10 flex flex-col md:flex-row justify-between items-center gap-6 text-[10px] text-zinc-600 font-mono font-bold uppercase tracking-[0.3em]">
             <div className="flex gap-8"><a href="#" className="hover:text-white">{t.footer.privacy}</a><a href="#" className="hover:text-white">{t.footer.terms}</a></div>
             <div className="flex items-center gap-6"><div className="flex items-center gap-3 px-4 py-1.5 rounded-full bg-zinc-900 border border-zinc-800"><div className="w-1.5 h-1.5 rounded-full bg-brand-500 animate-pulse"></div><span className="text-zinc-400">{t.footer.systemStatus}</span></div><span className="text-center md:text-right">&copy; 2026 AgroVibe. {t.footer.rightsReserved}</span></div>
         </div>
         <div className="mt-20 md:mt-32 select-none pointer-events-none text-center"><h1 className="text-[12vw] md:text-[14vw] font-black leading-none text-zinc-900 group-hover:text-zinc-800 transition-colors duration-1000 tracking-tighter uppercase italic">AGROVIBE</h1></div>
      </footer>

      {isLangMenuOpen && !isNavOpen && (
        <div className="fixed inset-0 z-50 flex items-end justify-center p-4 md:hidden">
           <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsLangMenuOpen(false)}></div>
           <div className="relative w-full max-w-sm bg-white dark:bg-zinc-900 rounded-[3rem] p-10 shadow-2xl animate-fade-up max-h-[70vh] flex flex-col overflow-hidden border border-zinc-200 dark:border-zinc-800">
              <div className="flex justify-between items-center mb-10 shrink-0"><h3 className="text-xl font-black uppercase italic tracking-tighter">{t.nav.selectLanguage}</h3><button onClick={() => setIsLangMenuOpen(false)} className="p-3 bg-zinc-100 dark:bg-zinc-800 rounded-full"><X size={20}/></button></div>
              <div className="flex flex-col gap-3 overflow-y-auto">
                 {(Object.keys(LANG_CONFIG) as Language[]).map((langKey) => (
                   <button key={langKey} onClick={() => { setLang(langKey); setIsLangMenuOpen(false); }} className={`flex items-center justify-between px-6 py-6 rounded-3xl border-2 transition-all shrink-0 ${lang === langKey ? 'bg-brand-50 dark:bg-brand-900/20 border-brand-500' : 'border-zinc-100 dark:border-zinc-800'}`}>
                     <div className="flex items-center gap-6"><span className="text-4xl">{LANG_CONFIG[langKey].flag}</span><div className="flex flex-col items-start"><span className="font-black text-lg uppercase italic tracking-tighter leading-none mb-1">{langKey}</span><span className="text-[10px] opacity-40 uppercase tracking-widest font-mono">Select Region</span></div></div>
                     {lang === langKey && <div className="w-8 h-8 bg-brand-500 rounded-full flex items-center justify-center text-white"><Check size={18} /></div>}
                   </button>
                 ))}
              </div>
           </div>
        </div>
      )}

      {cookieConsent === null && <CookieConsent t={t.cookieConsent} onAccept={() => setCookieConsent('accepted')} onDecline={() => setCookieConsent('declined')} />}

      {isClientModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-xl" onClick={() => setIsClientModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-zinc-900 w-full max-w-2xl rounded-[3rem] p-8 md:p-16 shadow-2xl border border-zinc-200 dark:border-zinc-800 animate-fade-up max-h-[95vh] overflow-y-auto">
            <button onClick={() => setIsClientModalOpen(false)} className="absolute top-8 right-8 p-3 rounded-full hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"><X size={20} /></button>
            <h3 className="text-3xl md:text-5xl font-black uppercase italic tracking-tighter mb-4">{t.clientForm.title}</h3>
            <p className="text-lg text-zinc-500 dark:text-zinc-400 mb-10 font-light leading-snug">{t.clientForm.subtitle}</p>
            <form className="space-y-6" onSubmit={(e) => { e.preventDefault(); alert("Inquiry sent!"); setIsClientModalOpen(false); }}>
               <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-3 text-zinc-400 italic">{t.clientForm.name}</label><input required type="text" className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-xl px-5 py-4 focus:outline-none focus:border-brand-500 font-bold transition-all" /></div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-3 text-zinc-400 italic">{t.clientForm.origin}</label><input required type="text" className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-xl px-5 py-4 focus:outline-none focus:border-brand-500 font-bold transition-all" /></div>
                 <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-3 text-zinc-400 italic">{t.clientForm.whatsapp}</label><input required type="tel" className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-xl px-5 py-4 focus:outline-none focus:border-brand-500 font-bold transition-all" /></div>
               </div>
               <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-3 text-zinc-400 italic">{t.clientForm.product}</label><select className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-xl px-5 py-4 focus:outline-none focus:border-brand-500 font-bold appearance-none transition-all uppercase tracking-widest text-xs">
                  {products.map(p => <option key={p.id} value={p.title}>{p.title}</option>)}
               </select></div>
               <button type="submit" className="w-full bg-brand-500 hover:bg-brand-600 text-white font-black uppercase italic tracking-tighter text-xl py-5 rounded-xl transition-all shadow-xl hover:shadow-brand-500/30 transform hover:scale-[1.02] active:scale-95">{t.clientForm.submit}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

