                              langKey === 'CN' ? 'Mandarin' :
                              langKey === 'JP' ? 'Japanese' :
                              langKey === 'KR' ? 'Korean' :
                              langKey === 'AE' ? 'Arabic' :
                              langKey === 'CH' ? 'Swiss' :
                              langKey === 'TR' ? 'Turkish' :
                              langKey === 'SE' ? 'Swedish' :
                              langKey === 'IN' ? 'Hindi' :
                              langKey === 'RU' ? 'Russian' :
                              langKey === 'VN' ? 'Tiếng Việt' :
                              langKey === 'TH' ? 'ไทย' :
