  ChevronRight, ChevronDown, BarChart3, Package, Truck, ShieldCheck, Mail, ArrowDown,
  Facebook, Linkedin, Instagram, Sprout, Leaf, Activity, Zap, MapPin, Phone, User, Check, Clock,
  Handshake, Microscope, Globe2, Scale, PackageCheck, Ship, Search, FlaskConical
} from 'lucide-react';
import { TRANSLATIONS, PRODUCTS, LANG_CONFIG } from './constants';
import { Language, Theme } from './types';
import AboutPage from './components/AboutPage';
import WhyUsPage from './components/WhyUsPage';
import PrivacyPage from './components/PrivacyPage';
import TermsPage from './components/TermsPage';
import CookieConsent from './components/CookieConsent';

type ViewState = 'home' | 'about' | 'why-us' | 'privacy' | 'terms';

function App() {
  // Initialize state from localStorage if available
  const [lang, setLang] = useState<Language>(() => {
    return (localStorage.getItem('greenwish_lang') as Language) || 'EN';
  });

  const [theme, setTheme] = useState<Theme>(() => {
    return (localStorage.getItem('greenwish_theme') as Theme) || 'light';
  });

  const [cookieConsent, setCookieConsent] = useState<'accepted' | 'declined' | null>(() => {
    return localStorage.getItem('greenwish_cookie_consent') as 'accepted' | 'declined' | null;
  });

  const [isNavOpen, setIsNavOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);

  // Store the INDEX of the active product to maintain selection across language changes
  const [activeProductIndex, setActiveProductIndex] = useState(0);

  const [scrolled, setScrolled] = useState(false);
  const [view, setView] = useState<ViewState>('home');
  const [worldTimes, setWorldTimes] = useState({ kendari: '', london: '', china: '' });
  const langMenuRef = useRef<HTMLDivElement>(null);

  const t = TRANSLATIONS[lang];
  const products = PRODUCTS[lang];
  const activeProduct = products[activeProductIndex];

  // Persist Language Choice
  useEffect(() => {
    if (cookieConsent === 'accepted') {
      localStorage.setItem('greenwish_lang', lang);
    }
  }, [lang, cookieConsent]);

  // Persist Theme Choice
  useEffect(() => {
    if (cookieConsent === 'accepted') {
      localStorage.setItem('greenwish_theme', theme);
    }

    if (theme === 'light') {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
  }, [theme, cookieConsent]);

  // RTL Logic for Arabic
  useEffect(() => {
    if (lang === 'AE') {
      document.documentElement.dir = 'rtl';
      document.documentElement.lang = 'ar';
    } else {
      document.documentElement.dir = 'ltr';
      document.documentElement.lang = lang.toLowerCase();
    }
  }, [lang]);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // World Time Updater
  useEffect(() => {
    const updateTime = () => {
      const getCityTime = (zone: string) => new Date().toLocaleTimeString('en-US', { 
        timeZone: zone, 
        hour: '2-digit', 
        minute: '2-digit',
        hour12: false 
      });

      setWorldTimes({
        kendari: getCityTime('Asia/Makassar'), // Kendari is in WITA (UTC+8) same as Makassar
        london: getCityTime('Europe/London'),
        china: getCityTime('Asia/Shanghai')
      });
    };
    updateTime();
    const interval = setInterval(updateTime, 1000); // Update every second for blinking effect preference
    return () => clearInterval(interval);
  }, []);

  // Close lang menu when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (langMenuRef.current && !langMenuRef.current.contains(event.target as Node)) {
        // Only close desktop menu here, mobile has its own overlay
        if (window.innerWidth >= 768) {
           setIsLangMenuOpen(false);
        }
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Scroll to top when view changes
  useEffect(() => {
    window.scrollTo(0, 0);
    setIsNavOpen(false); // Ensure nav closes on view change
  }, [view]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const handleCookieAccept = () => {
    setCookieConsent('accepted');
    localStorage.setItem('greenwish_cookie_consent', 'accepted');
    // Immediately save current preferences upon acceptance
    localStorage.setItem('greenwish_lang', lang);
    localStorage.setItem('greenwish_theme', theme);
  };

  const handleCookieDecline = () => {
    setCookieConsent('declined');
    localStorage.setItem('greenwish_cookie_consent', 'declined');
    // Clear existing preferences if declined
    localStorage.removeItem('greenwish_lang');
    localStorage.removeItem('greenwish_theme');
  };

  // Safe Navigation Handler
  const handleScrollTo = (e: React.MouseEvent<HTMLElement>, id: string) => {
    e.preventDefault(); // This stops the browser from trying to navigate to the #hash URL
    setView('home');
    setIsNavOpen(false);

    // Small timeout ensures the DOM is ready (switched to 'home') before scrolling
    setTimeout(() => {
      const element = document.getElementById(id);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
      }
    }, 100);
  };

  const isDark = theme === 'dark';

  return (
    <div className={`min-h-screen transition-colors duration-700 font-sans selection:bg-brand-500 selection:text-white ${isDark ? 'bg-zinc-950 text-zinc-100' : 'bg-[#f8f8f7] text-zinc-900'} overflow-x-hidden`}>

      {/* Noise Texture Overlay */}
      <div className="fixed inset-0 pointer-events-none z-0 bg-noise opacity-40 mix-blend-overlay"></div>

      {/* Navigation */}
      <nav className={`fixed top-0 left-0 w-full z-40 transition-all duration-500 ${scrolled ? 'py-3 md:py-4' : 'py-6 md:py-8'}`}>
        <div className="w-[92%] md:max-w-[95%] mx-auto bg-white/80 dark:bg-black/50 backdrop-blur-md border border-white/20 dark:border-white/10 rounded-full px-4 md:px-8 py-3 md:py-4 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow">
          {/* Brand */}
          <button onClick={() => setView('home')} className="flex items-center gap-2 md:gap-3 group">
             <div className="w-8 h-8 md:w-10 md:h-10 bg-brand-500 rounded-full flex items-center justify-center text-white group-hover:scale-110 transition-transform shrink-0">
                <Leaf size={18} fill="currentColor" />
             </div>
             <span className="font-bold text-lg md:text-xl tracking-tight uppercase">GREENWISH<span className="text-brand-500">.</span></span>
          </button>

          {/* Desktop Links */}
          <div className="hidden md:flex items-center gap-8 text-sm font-medium">
             <button onClick={() => setView('home')} className={`opacity-60 hover:opacity-100 hover:text-brand-500 transition-all ${view === 'home' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.home}</button>
             <button onClick={() => setView('about')} className={`opacity-60 hover:opacity-100 hover:text-brand-500 transition-all ${view === 'about' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.about}</button>
             <button onClick={() => setView('why-us')} className={`opacity-60 hover:opacity-100 hover:text-brand-500 transition-all ${view === 'why-us' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.whyChooseUs}</button>
             <a href="#services" onClick={(e) => handleScrollTo(e, 'services')} className="opacity-60 hover:opacity-100 hover:text-brand-500 transition-all">{t.nav.services}</a>
             <a href="#products" onClick={(e) => handleScrollTo(e, 'products')} className="opacity-60 hover:opacity-100 hover:text-brand-500 transition-all">{t.nav.products}</a>
             <a href="#specs" onClick={(e) => handleScrollTo(e, 'specs')} className="opacity-60 hover:opacity-100 hover:text-brand-500 transition-all">{t.nav.specs}</a>
          </div>

          {/* Actions */}
          <div className="hidden md:flex items-center gap-3 lg:gap-4">
             <button onClick={toggleTheme} className="w-10 h-10 rounded-full border border-zinc-200 dark:border-zinc-800 flex items-center justify-center hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors">
                {isDark ? <Sun size={18} /> : <Moon size={18} />}
             </button>

             {/* Language Dropdown */}
             <div className="relative" ref={langMenuRef}>
               <button 
                 onClick={() => setIsLangMenuOpen(!isLangMenuOpen)}
                 className={`w-10 h-10 rounded-full border border-zinc-200 dark:border-zinc-800 flex items-center justify-center hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors ${isLangMenuOpen ? 'bg-zinc-100 dark:bg-zinc-800 ring-2 ring-brand-500/20' : ''}`}
                 title={t.nav.selectLanguage}
               >
                  <Globe size={18} />
               </button>

               {isLangMenuOpen && (
                 <div className="absolute top-full right-0 rtl:right-auto rtl:left-0 mt-3 w-44 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-2xl shadow-xl overflow-hidden animate-fade-up z-50">
                   <div className="p-1.5 flex flex-col gap-0.5 max-h-[300px] overflow-y-auto">
                     {(Object.keys(LANG_CONFIG) as Language[]).map((langKey) => (
                       <button
                         key={langKey}
                         onClick={() => { setLang(langKey); setIsLangMenuOpen(false); }}
                         className={`flex items-center justify-between px-3 py-2.5 text-sm rounded-xl transition-colors ${
                           lang === langKey 
                             ? 'bg-zinc-100 dark:bg-zinc-800 font-bold' 
                             : 'hover:bg-zinc-50 dark:hover:bg-zinc-800/50'
                         }`}
                       >
                         <div className="flex items-center gap-3">
                           <span className="text-lg">{LANG_CONFIG[langKey].flag}</span>
                           <span>{LANG_CONFIG[langKey].label}</span>
                         </div>
                         {lang === langKey && <Check size={14} className="text-brand-500" />}
                       </button>
                     ))}
                   </div>
                 </div>
               )}
             </div>

             {/* New Client Button */}
             <button 
               onClick={() => setIsClientModalOpen(true)}
               className="px-6 py-2.5 bg-brand-500 text-white rounded-full text-sm font-semibold hover:bg-brand-600 transition-all flex items-center gap-2 shadow-lg shadow-brand-500/20 active:scale-95 whitespace-nowrap"
             >
                <User size={16} />
                {t.nav.client}
             </button>
          </div>

           {/* Mobile Toggle */}
           <div className="md:hidden flex items-center gap-2">
             <button 
                onClick={() => { setIsLangMenuOpen(!isLangMenuOpen); setIsNavOpen(false); }} 
                className={`p-2 rounded-full border border-zinc-200 dark:border-zinc-800 transition-colors ${isLangMenuOpen ? 'bg-zinc-100 dark:bg-zinc-800' : ''}`}
             >
               <Globe size={20} />
             </button>
             <button 
                onClick={() => { setIsNavOpen(!isNavOpen); setIsLangMenuOpen(false); }}
                className="p-2 rounded-full bg-zinc-900 dark:bg-white text-white dark:text-zinc-900"
             >
               {isNavOpen ? <X size={20} /> : <Menu size={20} />}
             </button>
           </div>
        </div>
      </nav>

      {/* Mobile Menu Overlay */}
      {isNavOpen && (
        <div className="fixed inset-0 z-30 bg-white/95 dark:bg-zinc-950/95 backdrop-blur-xl pt-32 px-6 overflow-y-auto pb-10 animate-fade-up">
           <div className="flex flex-col gap-8">
              <div className="flex flex-col gap-4 text-3xl font-light">
                 <button onClick={() => { setView('home'); setIsNavOpen(false); }} className={`text-left py-2 border-b border-zinc-100 dark:border-zinc-800 ${view === 'home' ? 'font-bold text-brand-500' : ''}`}>{t.nav.home}</button>
                 <button onClick={() => { setView('about'); setIsNavOpen(false); }} className={`text-left py-2 border-b border-zinc-100 dark:border-zinc-800 ${view === 'about' ? 'font-bold text-brand-500' : ''}`}>{t.nav.about}</button>
                 <button onClick={() => { setView('why-us'); setIsNavOpen(false); }} className={`text-left py-2 border-b border-zinc-100 dark:border-zinc-800 ${view === 'why-us' ? 'font-bold text-brand-500' : ''}`}>{t.nav.whyChooseUs}</button>
                 <a href="#services" onClick={(e) => handleScrollTo(e, 'services')} className="text-left py-2 border-b border-zinc-100 dark:border-zinc-800">{t.nav.services}</a>
                 <a href="#products" onClick={(e) => handleScrollTo(e, 'products')} className="text-left py-2 border-b border-zinc-100 dark:border-zinc-800">{t.nav.products}</a>
                 <a href="#specs" onClick={(e) => handleScrollTo(e, 'specs')} className="text-left py-2 border-b border-zinc-100 dark:border-zinc-800">{t.nav.specs}</a>
              </div>

              <button 
                onClick={() => { setIsNavOpen(false); setIsClientModalOpen(true); }} 
                className="w-full py-4 bg-brand-500 text-white rounded-2xl text-lg font-bold shadow-lg shadow-brand-500/20 flex items-center justify-center gap-2"
              >
                <User /> {t.nav.client}
              </button>

              <div className="pt-4 flex items-center justify-between">
                <span className="text-sm opacity-50 font-mono uppercase tracking-widest">{t.nav.themeSettings}</span>
                <button onClick={toggleTheme} className="flex items-center gap-3 px-4 py-2 rounded-full border border-zinc-200 dark:border-zinc-800">
                   <span className="text-sm font-bold">{isDark ? t.nav.darkMode : t.nav.lightMode}</span>
                   {isDark ? <Sun size={18} /> : <Moon size={18} />}
                </button>
              </div>
           </div>
        </div>
      )}

      {/* Language Menu for Mobile Trigger (Overlay) */}
      {(isLangMenuOpen && !isNavOpen) && (
        <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center p-4 md:hidden">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsLangMenuOpen(false)}></div>
           <div className="relative w-full max-w-sm bg-white dark:bg-zinc-900 rounded-3xl p-6 shadow-2xl animate-fade-up max-h-[70vh] flex flex-col">
              <div className="flex justify-between items-center mb-6 shrink-0">
                <h3 className="text-lg font-bold">{t.nav.selectLanguage}</h3>
                <button onClick={() => setIsLangMenuOpen(false)} className="p-2 bg-zinc-100 dark:bg-zinc-800 rounded-full"><X size={16}/></button>
              </div>
              <div className="flex flex-col gap-2 overflow-y-auto">
                 {(Object.keys(LANG_CONFIG) as Language[]).map((langKey) => (
                   <button
                     key={langKey}
                     onClick={() => { setLang(langKey); setIsLangMenuOpen(false); }}
                     className={`flex items-center justify-between px-4 py-4 rounded-xl border transition-colors shrink-0 ${
                       lang === langKey 
                         ? 'bg-brand-50 dark:bg-brand-900/20 border-brand-500' 
                         : 'border-zinc-100 dark:border-zinc-800 hover:bg-zinc-50 dark:hover:bg-zinc-800/50'
                     }`}
                   >
                     <div className="flex items-center gap-3">
                       <span className="text-3xl">{LANG_CONFIG[langKey].flag}</span>
                       <div className="flex flex-col items-start">
                         <span className="font-bold text-base">
                             {langKey === 'EN' ? 'English' : 
                              langKey === 'ID' ? 'Bahasa Indonesia' : 
                              langKey === 'CN' ? 'Mandarin' :
                              langKey === 'JP' ? 'Japanese' :
                              langKey === 'KR' ? 'Korean' :
                              langKey === 'AE' ? 'Arabic' :
                              langKey === 'CH' ? 'Swiss' :
                              langKey === 'TR' ? 'Turkish' :
                              langKey === 'SE' ? 'Swedish' :
                              langKey === 'IN' ? 'Hindi' :
                              langKey === 'RU' ? 'Russian' :
                              langKey === 'VN' ? 'Tiếng Việt' :
                              langKey === 'TH' ? 'ไทย' :
                              langKey}
                         </span>
                         <span className="text-xs opacity-50 uppercase tracking-wider">{LANG_CONFIG[langKey].label}</span>
                       </div>
                     </div>
                     {lang === langKey && <div className="w-6 h-6 bg-brand-500 rounded-full flex items-center justify-center text-white"><Check size={14} /></div>}
                   </button>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Cookie Consent Banner */}
      {cookieConsent === null && (
        <CookieConsent 
          t={t.cookieConsent} 
          onAccept={handleCookieAccept} 
          onDecline={handleCookieDecline} 
        />
      )}

      {/* Client Modal Form */}
      {isClientModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsClientModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-zinc-900 w-full max-w-lg rounded-3xl p-6 md:p-8 shadow-2xl border border-zinc-200 dark:border-zinc-800 animate-fade-up max-h-[90vh] overflow-y-auto">
            <button 
              onClick={() => setIsClientModalOpen(false)}
              className="absolute top-4 right-4 md:top-6 md:right-6 p-2 rounded-full hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors rtl:right-auto rtl:left-4 md:rtl:left-6"
            >
              <X size={20} />
            </button>

            <h3 className="text-2xl font-bold mb-2">{t.clientForm.title}</h3>
            <p className="text-sm text-zinc-500 dark:text-zinc-400 mb-6 md:mb-8">{t.clientForm.subtitle}</p>

            <form className="space-y-4 md:space-y-5" onSubmit={(e) => { e.preventDefault(); alert("Inquiry sent!"); setIsClientModalOpen(false); }}>
               <div>
                  <label className="block text-xs font-bold uppercase tracking-wider mb-2 text-zinc-500">{t.clientForm.name}</label>
                  <input required type="text" className="w-full bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl px-4 py-3 focus:outline-none focus:border-brand-500 transition-colors" />
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
                    <label className="block text-xs font-bold uppercase tracking-wider mb-2 text-zinc-500">{t.clientForm.origin}</label>
                    <input required type="text" className="w-full bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl px-4 py-3 focus:outline-none focus:border-brand-500 transition-colors" />
                 </div>
                 <div>
                    <label className="block text-xs font-bold uppercase tracking-wider mb-2 text-zinc-500">{t.clientForm.whatsapp}</label>
                    <input required type="tel" className="w-full bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl px-4 py-3 focus:outline-none focus:border-brand-500 transition-colors" />
                 </div>
               </div>

               <div>
                  <label className="block text-xs font-bold uppercase tracking-wider mb-2 text-zinc-500">{t.clientForm.email}</label>
                  <input required type="email" className="w-full bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl px-4 py-3 focus:outline-none focus:border-brand-500 transition-colors" />
               </div>

               <div>
                  <label className="block text-xs font-bold uppercase tracking-wider mb-2 text-zinc-500">{t.clientForm.product}</label>
                  <select className="w-full bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-xl px-4 py-3 focus:outline-none focus:border-brand-500 transition-colors appearance-none">
                     {products.map(p => <option key={p.id} value={p.title}>{p.title}</option>)}
                  </select>
               </div>

               <button type="submit" className="w-full bg-brand-500 hover:bg-brand-600 text-white font-bold py-4 rounded-xl transition-all shadow-lg hover:shadow-brand-500/20 mt-4">
                  {t.clientForm.submit}
               </button>
            </form>
          </div>
        </div>
      )}

      {/* Main Content Switcher */}
      {view === 'about' ? (
        <AboutPage t={t} isDark={isDark} />
      ) : view === 'why-us' ? (
        <WhyUsPage t={t} isDark={isDark} />
      ) : view === 'privacy' ? (
        <PrivacyPage t={t} isDark={isDark} />
      ) : view === 'terms' ? (
        <TermsPage t={t} isDark={isDark} />
      ) : (
        <>
          {/* Hero Section */}
          <header className="relative pt-32 md:pt-60 pb-16 md:pb-20 px-4 md:px-12 overflow-hidden">
             <div className="max-w-[90rem] mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-12 items-end">
                <div className="lg:col-span-8 relative z-10">
                   <div className="inline-flex items-center gap-2 mb-6 md:mb-8 border border-zinc-200 dark:border-zinc-800 px-3 py-1.5 md:px-4 md:py-2 rounded-full text-[10px] md:text-xs uppercase tracking-widest font-bold animate-fade-up opacity-0" style={{animationDelay: '0.1s'}}>
                      <span className="w-2 h-2 rounded-full bg-brand-500 animate-pulse"></span>
                      {t.hero.badge}
                   </div>
                   <h1 className="text-[12vw] md:text-8xl lg:text-[7rem] font-bold leading-[0.9] tracking-tight mb-6 md:mb-8 text-balance animate-fade-up opacity-0" style={{animationDelay: '0.2s'}}>
                      {t.hero.titleLine1} <br/>
                      <span className="text-brand-500">{t.hero.titleLine2}</span>
                   </h1>
                   <p className="text-base md:text-xl opacity-60 max-w-xl leading-relaxed mb-8 md:mb-12 animate-fade-up opacity-0" style={{animationDelay: '0.3s'}}>
                      {t.hero.subtitle}
                   </p>
                   <div className="flex flex-col sm:flex-row gap-4 animate-fade-up opacity-0" style={{animationDelay: '0.4s'}}>
                      <a href="#products" onClick={(e) => handleScrollTo(e, 'products')} className="group px-8 py-4 bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 rounded-full text-sm font-bold flex items-center justify-center gap-2 transition-all hover:pr-6 rtl:hover:pr-8 rtl:hover:pl-6">
                         {t.hero.ctaPrimary} <ArrowRight size={18} className="group-hover:translate-x-1 rtl:group-hover:-translate-x-1 transition-transform" />
                      </a>
                      <button onClick={() => setIsClientModalOpen(true)} className="px-8 py-4 border border-zinc-200 dark:border-zinc-800 rounded-full text-sm font-bold hover:bg-zinc-100 dark:hover:bg-zinc-900 transition-colors">
                         {t.hero.ctaSecondary}
                      </button>
                   </div>
                </div>

                {/* Abstract visual */}
                <div className="lg:col-span-4 relative h-[300px] md:h-[400px] lg:h-[500px] w-full animate-reveal opacity-0 mt-8 lg:mt-0" style={{animationDelay: '0.5s'}}>
                   <div className="absolute inset-0 bg-gradient-to-tr from-brand-500/20 to-transparent rounded-3xl rotate-3 scale-95 z-0"></div>
                   <div className="absolute inset-0 bg-zinc-200 dark:bg-zinc-900 rounded-3xl overflow-hidden z-10 shadow-2xl">
                      <img 
                        src="https://images.unsplash.com/photo-1599940824399-b87987ce179a?q=80&w=2624&auto=format&fit=crop" 
                        className="w-full h-full object-cover opacity-80 scale-110 hover:scale-100 transition-transform duration-[2s]"
                        alt="Spices"
                      />
                      <div className="absolute bottom-4 left-4 right-4 md:bottom-6 md:left-6 md:right-6 p-4 bg-white/10 backdrop-blur-md rounded-2xl border border-white/20">
                         <div className="flex justify-between items-center text-white">
                            <span className="text-xs font-mono uppercase">{t.hero.currentVol}</span>
                            <span className="font-bold font-mono">240 MT</span>
                         </div>
                         <div className="w-full bg-white/20 h-1 mt-2 rounded-full overflow-hidden">
                            <div className="bg-brand-500 h-full w-[70%]"></div>
                         </div>
                      </div>
                   </div>
                </div>
             </div>
          </header>

          {/* Infinite Marquee */}
          <div className="w-full bg-brand-500 text-brand-950 py-4 md:py-6 overflow-hidden border-y border-brand-600">
             <div className="flex gap-16 animate-marquee whitespace-nowrap font-mono text-sm md:text-lg font-bold uppercase tracking-wider items-center rtl:flex-row-reverse">
