import React, { useState, useEffect, useRef } from 'react';
import { 
  Menu, X, Globe, Moon, Sun, ArrowRight, ArrowUpRight,
  ChevronRight, ChevronDown, BarChart3, Package, Truck, ShieldCheck, Mail, ArrowDown,
  Facebook, Linkedin, Instagram, Sprout, Leaf, Activity, Zap, MapPin, Phone, User, Check, Clock,
  Handshake, Microscope, Globe2, Scale, PlayCircle
} from 'lucide-react';
import { TRANSLATIONS, PRODUCTS, LANG_CONFIG } from './constants';
import { Language, Theme } from './types';
import AboutPage from './components/AboutPage';
import WhyUsPage from './components/WhyUsPage';
import PrivacyPage from './components/PrivacyPage';
import TermsPage from './components/TermsPage';
import ProductDetailPage from './components/ProductDetailPage';
import CatalogPage from './components/CatalogPage';
import CookieConsent from './components/CookieConsent';

type ViewState = 'home' | 'about' | 'why-us' | 'privacy' | 'terms' | 'product-detail' | 'catalog';

function App() {
  // Initialize state from localStorage if available
  const [lang, setLang] = useState<Language>(() => {
    return (localStorage.getItem('greenwish_lang') as Language) || 'EN';
  });

  const [theme, setTheme] = useState<Theme>(() => {
    return (localStorage.getItem('greenwish_theme') as Theme) || 'light';
  });

  const [cookieConsent, setCookieConsent] = useState<'accepted' | 'declined' | null>(() => {
    return localStorage.getItem('greenwish_cookie_consent') as 'accepted' | 'declined' | null;
  });

  const [isNavOpen, setIsNavOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);

  // Store the INDEX of the active product to maintain selection across language changes
  const [activeProductIndex, setActiveProductIndex] = useState(0);

  const [scrolled, setScrolled] = useState(false);
  const [view, setView] = useState<ViewState>('home');
  const [worldTimes, setWorldTimes] = useState({ kendari: '', london: '', china: '' });
  const langMenuRef = useRef<HTMLDivElement>(null);

  const t = TRANSLATIONS[lang];
  const products = PRODUCTS[lang];
  const activeProduct = products[activeProductIndex];

  // Persist Language Choice
  useEffect(() => {
    if (cookieConsent === 'accepted') {
      localStorage.setItem('greenwish_lang', lang);
    }
  }, [lang, cookieConsent]);

  // Persist Theme Choice
  useEffect(() => {
    if (cookieConsent === 'accepted') {
      localStorage.setItem('greenwish_theme', theme);
    }

    if (theme === 'light') {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
  }, [theme, cookieConsent]);

  // RTL Logic for Arabic
  useEffect(() => {
    if (lang === 'AE') {
      document.documentElement.dir = 'rtl';
      document.documentElement.lang = 'ar';
    } else {
      document.documentElement.dir = 'ltr';
      document.documentElement.lang = lang.toLowerCase();
    }
  }, [lang]);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // World Time Updater
  useEffect(() => {
    const updateTime = () => {
      const getCityTime = (zone: string) => new Date().toLocaleTimeString('en-US', { 
        timeZone: zone, 
        hour: '2-digit', 
        minute: '2-digit',
        hour12: false 
      });

      setWorldTimes({
        kendari: getCityTime('Asia/Makassar'), // Kendari is in WITA (UTC+8) same as Makassar
        london: getCityTime('Europe/London'),
        china: getCityTime('Asia/Shanghai')
      });
    };
    updateTime();
    const interval = setInterval(updateTime, 1000); // Update every second for blinking effect preference
    return () => clearInterval(interval);
  }, []);

  // Close lang menu when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (langMenuRef.current && !langMenuRef.current.contains(event.target as Node)) {
        // Only close desktop menu here, mobile has its own overlay
        if (window.innerWidth >= 768) {
           setIsLangMenuOpen(false);
        }
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Scroll to top when view changes
  useEffect(() => {
    window.scrollTo(0, 0);
    setIsNavOpen(false); // Ensure nav closes on view change
  }, [view]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const handleCookieAccept = () => {
    setCookieConsent('accepted');
    localStorage.setItem('greenwish_cookie_consent', 'accepted');
    // Immediately save current preferences upon acceptance
    localStorage.setItem('greenwish_lang', lang);
    localStorage.setItem('greenwish_theme', theme);
  };

  const handleCookieDecline = () => {
    setCookieConsent('declined');
    localStorage.setItem('greenwish_cookie_consent', 'declined');
    // Clear existing preferences if declined
    localStorage.removeItem('greenwish_lang');
    localStorage.removeItem('greenwish_theme');
  };

  // Safe Navigation Handler
  const handleScrollTo = (e: React.MouseEvent<HTMLElement>, id: string) => {
    e.preventDefault(); // This stops the browser from trying to navigate to the #hash URL
    setView('home');
    setIsNavOpen(false);

    // Small timeout ensures the DOM is ready (switched to 'home') before scrolling
    setTimeout(() => {
      const element = document.getElementById(id);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
      }
    }, 100);
  };

  const handleProductClick = (index: number) => {
    setActiveProductIndex(index);
    setView('product-detail');
  };

  const handleClientSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const name = formData.get('name');
    const origin = formData.get('origin');
    const phone = formData.get('phone');
    const email = formData.get('email');
    const product = formData.get('product');

    // Create WhatsApp message
    const text = `Hello Greenwish, I would like to request a quotation.\n\n` +
                 `Name: ${name}\n` +
                 `Company/Origin: ${origin}\n` +
                 `WhatsApp/Contact: ${phone}\n` +
                 `Email: ${email}\n` +
                 `Product Interest: ${product}`;

    const encodedText = encodeURIComponent(text);
    // WhatsApp number 081775030638 -> 6281775030638
    const whatsappUrl = `https://wa.me/6281775030638?text=${encodedText}`;

    window.open(whatsappUrl, '_blank');
    setIsClientModalOpen(false);
  };

  const isDark = theme === 'dark';

  return (
    <div className={`min-h-screen transition-colors duration-700 font-sans selection:bg-brand-500 selection:text-white ${isDark ? 'bg-zinc-950 text-white' : 'bg-[#f4f4f5] text-zinc-900'} overflow-x-hidden`}>

      {/* Noise Texture Overlay */}
      <div className="fixed inset-0 pointer-events-none z-0 bg-noise opacity-[0.06] mix-blend-overlay"></div>

      {/* Navigation */}
      <nav className={`fixed top-0 left-0 w-full z-40 transition-all duration-500 ${scrolled ? 'py-3' : 'py-6 md:py-8'}`}>
        <div className={`w-[92%] md:max-w-[90rem] mx-auto transition-all duration-500 rounded-full px-4 md:px-6 py-3 flex justify-between items-center ${scrolled ? 'bg-white/80 dark:bg-black/60 backdrop-blur-xl border border-white/20 dark:border-white/10 shadow-lg shadow-black/5' : 'bg-transparent'}`}>
          {/* Brand */}
          <button onClick={() => setView('home')} className="flex items-center gap-2 md:gap-3 group">
             <div className="w-8 h-8 md:w-10 md:h-10 bg-gradient-to-br from-brand-400 to-brand-600 rounded-xl rotate-3 flex items-center justify-center text-white group-hover:rotate-12 transition-transform shadow-lg shadow-brand-500/30">
                <Leaf size={18} fill="currentColor" />
             </div>
             <span className="font-bold text-lg md:text-xl tracking-tight uppercase font-fun">GREENWISH<span className="text-brand-500">.</span></span>
          </button>

          {/* Desktop Links */}
          <div className={`hidden md:flex items-center gap-1 p-1 rounded-full ${scrolled ? '' : 'bg-white/50 dark:bg-black/20 backdrop-blur-md border border-white/40 dark:border-white/5'}`}>
             {[
               { id: 'home', label: t.nav.home, action: () => setView('home') },
               { id: 'about', label: t.nav.about, action: () => setView('about') },
               { id: 'why-us', label: t.nav.whyChooseUs, action: () => setView('why-us') },
             ].map(link => (
               <button 
                 key={link.id}
                 onClick={link.action} 
                 className={`px-5 py-2 rounded-full text-sm font-medium transition-all ${view === link.id ? 'bg-white dark:bg-zinc-800 shadow-sm text-brand-600 dark:text-brand-400' : 'hover:bg-white/50 dark:hover:bg-white/10 text-zinc-600 dark:text-zinc-400'}`}
               >
                 {link.label}
               </button>
             ))}
             <a href="#products" onClick={(e) => handleScrollTo(e, 'products')} className="px-5 py-2 rounded-full text-sm font-medium hover:bg-white/50 dark:hover:bg-white/10 text-zinc-600 dark:text-zinc-400 transition-all">{t.nav.products}</a>
             <a href="#specs" onClick={(e) => handleScrollTo(e, 'specs')} className="px-5 py-2 rounded-full text-sm font-medium hover:bg-white/50 dark:hover:bg-white/10 text-zinc-600 dark:text-zinc-400 transition-all">{t.nav.specs}</a>
          </div>

          {/* Actions */}
          <div className="hidden md:flex items-center gap-3 lg:gap-4">
             <button onClick={toggleTheme} className="w-10 h-10 rounded-full border border-zinc-200 dark:border-zinc-800 flex items-center justify-center bg-white/50 dark:bg-black/20 hover:bg-white dark:hover:bg-zinc-800 transition-colors">
                {isDark ? <Sun size={18} /> : <Moon size={18} />}
             </button>

             {/* Language Dropdown */}
             <div className="relative" ref={langMenuRef}>
               <button 
                 onClick={() => setIsLangMenuOpen(!isLangMenuOpen)}
                 className={`w-10 h-10 rounded-full border border-zinc-200 dark:border-zinc-800 flex items-center justify-center bg-white/50 dark:bg-black/20 hover:bg-white dark:hover:bg-zinc-800 transition-colors ${isLangMenuOpen ? 'ring-2 ring-brand-500/20' : ''}`}
                 title={t.nav.selectLanguage}
               >
                  <Globe size={18} />
               </button>

               {isLangMenuOpen && (
                 <div className="absolute top-full right-0 rtl:right-auto rtl:left-0 mt-3 w-48 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-2xl shadow-2xl overflow-hidden animate-fade-up z-50">
                   <div className="p-2 flex flex-col gap-1 max-h-[300px] overflow-y-auto custom-scrollbar">
                     {(Object.keys(LANG_CONFIG) as Language[]).map((langKey) => (
                       <button
