                 <button onClick={() => { setView('about'); setIsNavOpen(false); }} className={`text-left py-2 border-b border-zinc-100 dark:border-zinc-800 ${view === 'about' ? 'font-bold text-brand-500' : ''}`}>{t.nav.about}</button>
