                   <li><a href="#sustainability" onClick={(e) => handleScrollTo(e, 'sustainability')} className="hover:text-brand-400 transition-colors hover:translate-x-2 inline-block duration-300 rtl:hover:-translate-x-2">{t.nav.sustainability}</a></li>
