             <div>
                <span className="block text-xs font-mono text-brand-400 mb-8 uppercase tracking-widest">{t.footer.connectLabel}</span>
                <ul className="space-y-4 text-xl md:text-2xl font-medium">
                   <li><a href="mailto:hello@greenwish.tech" className="hover:text-brand-400 transition-colors flex items-center gap-2 group/link">Gmail <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                   <li><a href="#" className="hover:text-brand-400 transition-colors flex items-center gap-2 group/link">TikTok <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                   <li><a href="#" className="hover:text-brand-400 transition-colors flex items-center gap-2 group/link">LinkedIn <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                   <li><a href="#" className="hover:text-brand-400 transition-colors flex items-center gap-2 group/link">Instagram <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                   <li><a href="#" className="hover:text-brand-400 transition-colors flex items-center gap-2 group/link">WeChat <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                </ul>
             </div>

             {/* Column 3: Contact */}
             <div className="lg:col-span-2">
                <span className="block text-xs font-mono text-brand-400 mb-8 uppercase tracking-widest">{t.footer.officeLabel}</span>
