         </div>

         {/* Bottom Section: Footer Meta */}
         <div className="max-w-[95rem] mx-auto border-t border-brand-900 pt-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-6 text-xs md:text-sm text-brand-400 font-mono">
