         {/* Giant Background Typography */}
         <div className="mt-20 select-none pointer-events-none">
            <h1 className="text-[18vw] font-black leading-none text-center text-brand-900 group-hover:text-brand-800 transition-colors duration-700 tracking-tighter">
               GREENWISH
            </h1>
