const buildProducts = (lang: Language): Product[] => {
  const texts = PRODUCT_TEXT[lang] || PRODUCT_TEXT['EN'];
  return BASE_PRODUCTS.map(p => ({
    ...p,
    title: texts[p.id]?.title || p.title,
    description: texts[p.id]?.desc || p.description,
    tags: texts[p.id]?.tags || p.tags
  }));
};

